import{z as B,x as s,o as l,c as p,q as r,j as i,D as E,d as A,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"PAG 与淬灭剂","description":"","frontmatter":{"title":"PAG 与淬灭剂","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pag-quencher.md","filePath":"litho/pag-quencher.md","lastUpdated":1791063341000}'),d={name:"litho/pag-quencher.md"};function h(P,a,m,D,u,G){const t=s("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="pag-与淬灭剂" tabindex="-1">PAG 与淬灭剂 <a class="header-anchor" href="#pag-与淬灭剂" aria-label="Permalink to &quot;PAG 与淬灭剂&quot;">​</a></h1><div class="epigraph"><p>PAG 决定酸从哪出生、生多少；淬灭剂决定酸走多远之前被收掉、阈值钉在哪。两个浓度是一对，不是两个独立的「越好」。</p><footer>—— 据 Ito / Willson 化学放大思路，以及 Mack 对产酸–中和阈值的表述整理</footer></div><p><a href="/litho/car-resist">上一课</a>把 CAR 写成 PAG 产酸、PEB 催化脱保护。配方里已经点名淬灭剂，但只承认「阈值不完全由光学 \\(I_\\mathrm{th}\\) 决定」。缺口是把产酸剂与碱淬灭写成一对旋钮：加载、量子产率、中和当量。淬灭剂加到多少算够、只买到多少裕量，留给<a href="/litho/quencher-loading">下一课</a>；PEB 温度怎么同时改增益与扩散，是后面的 PEB 课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAR 的潜像在曝光结束时是酸的空间分布。酸从 PAG 来：典型 DUV 用鎓盐，吸收（或经敏化）后放出强酸。同一空中像，PAG 加载高、产率高，酸图亮；加载低，要靠加剂量或后面 PEB 课加烘时间来凑脱保护。缺口不是再讲一遍催化循环，而是：酸图的幅度与暗区漏酸，由谁压住。</p><p>淬灭剂（碱）在膜里预置一个酸的汇。未曝光区里漂进来的酸、以及环境胺之外的「配方内」中和，都走这个汇。暗区溶速能否保持足够低、阈值剂量 \\(E_0\\) 钉在哪，首先是 PAG 与淬灭剂的当量差，其次才是光学 \\(I\\)。</p><p><span class="marginnote">PAG（光酸发生剂）就是「被光触发才产酸的分子」：平时是稳定的盐，吸收一个光子后裂解、放出一个强酸分子。可以把它想成埋在胶里的微型酸手雷——曝光点到谁，谁就在后烘时引爆，酸再去当催化剂拆保护基。</span></p><h3 id="阈值是化学的-然后才是光学的" tabindex="-1">阈值是化学的，然后才是光学的 <a class="header-anchor" href="#阈值是化学的-然后才是光学的" aria-label="Permalink to &quot;阈值是化学的，然后才是光学的&quot;">​</a></h3><p>简单图像：有效酸 \\(\\approx\\) 生成酸 \\(-\\) 淬灭剂。生成酸随剂量近乎线性（低剂量、无漂白极限时），于是存在一个剂量门槛才打得过碱。光学对比决定门槛附近酸图有多陡；淬灭剂决定门槛的高度。把 \\(I_\\mathrm{th}\\) 写成镜头规格，会把配方当成玻璃。</p><p><span class="marginnote">环境胺（T-topping）是额外的、从表面进来的淬灭。它让顶部阈值升高、出现 T 形剖面。配方内淬灭剂可以提高抗污染能力，却同时抬 \\(E_0\\)。上层涂层管的是这件事，不改 PAG 的定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程旋钮：PAG 种类（酸强度、体积、吸收截面）与质量分数；淬灭剂种类与分数；有时还有光可分解淬灭剂，曝光区把碱自己拆掉，暗区仍留着——本课只承认有这种不对称，不写分子式。摩尔比比重量百分比更接近化学当量：同一 wt% 换一种分子量更大的 PAG，产酸数会变。吸收必须落在曝光波长：193 nm 上聚合物本身已经吸收，把全部吸收算进 PAG 会高估产酸。</p><p><span class="marginnote">为什么摩尔比比 wt% 靠谱：两种 PAG 分子量若差一倍，同样加 5 wt%，重的那种分子数只有一半，产酸上限也随之减半。配方表只写质量分数时，换一种 PAG 就悄悄换掉了化学当量——当量差才是阈值的主人。</span></p><p>表征：测 \\(E_0\\)、衬度、暗侵蚀随 PAG/淬灭剂比的变化；用同一光学、只改这一对，CD 与 LWR 会一起动。后课扩散长度 \\(\\ell\\) 会把淬灭剂写成缩短酸程的项；本课先把它写成阈值与暗区安全裕量。环境稳定性实验（延迟 PEB、暴露于胺）是淬灭剂是否够的判据之一，不要只用灵敏度一张图签核配方。</p><h3 id="增益与泄漏" tabindex="-1">增益与泄漏 <a class="header-anchor" href="#增益与泄漏" aria-label="Permalink to &quot;增益与泄漏&quot;">​</a></h3><p>PAG 多，灵敏度好，扫描可以快。暗区 PAG 也会被杂散光、flare 微弱产酸，淬灭剂不够就会起雾、掉暗区厚度。一对浓度必须联合标定。Ito / Willson 的放大解决的是「光子少、反应要多」；淬灭剂解决的是「放大之后暗区不能也亮」。</p>',16)),(l(),i(n,null,{default:E(()=>[o(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%89%82%E9%87%8F%22%5D%20--%3E%20PAG%5B%22PAG%20%E4%BA%A7%E9%85%B8%22%5D%0A%20%20PAG%20--%3E%20NET%5B%22%E6%9C%89%E6%95%88%E9%85%B8%22%5D%0A%20%20Q%5B%22%E6%B7%AC%E7%81%AD%E5%89%82%E7%A2%B1%22%5D%20--%3E%20NET%0A%20%20NET%20--%3E%20TH%5B%22%E5%8C%96%E5%AD%A6%E9%98%88%E5%80%BC%22%5D%0A%20%20TH%20--%3E%20PEB%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9APEB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"光子（DUV）直接或经能量转移把 PAG 打成酸。酸在 PEB 里当催化剂，直到被淬灭或扩散离开。亮区中心淬灭剂先被耗尽，催化全速；边沿是产酸与淬灭的争夺带，阈值轮廓就在这条带上。加淬灭剂：争夺带变窄、有效 \\(\\ell\\) 下降（后面酸扩散课展开）、灵敏度下降。这是 RLS 三角在配方上的具体旋钮，本课先记下「一对」，不写 LWR 谱。flare 与杂散把暗区剂量从零抬起时，淬灭剂就是暗区的保险丝；光学课的杂散光在这里变成化学库存够不够。",-1)),a[5]||(a[5]=e("p",null,"酸体积大、淬灭快，模糊小、往往更不敏。酸体积小、扩散快，相反。种类选择与加载是同一预算的两个轴，不能只报「PAG wt%」。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"负胶 CAR 用酸催化交联，淬灭剂仍在收酸，只是「留下」的是曝光区。本课默认正性脱保护 CAR，与上一课同一工作点。")],-1)),(l(),i(n,null,{default:E(()=>[o(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E5%9B%BE%E5%BD%A2%E8%BE%B9%E6%B2%BF%22%5D%20--%3E%20BRIGHT%5B%22%E4%BA%AE%E5%8C%BA%E4%BE%A7%3A%20%E6%B7%AC%E7%81%AD%E5%89%82%E8%80%97%E5%B0%BD%2C%20%E5%82%AC%E5%8C%96%E5%85%A8%E9%80%9F%22%5D%0A%20%20EDGE%20--%3E%20DARK%5B%22%E6%9A%97%E5%8C%BA%E4%BE%A7%3A%20%E6%B7%AC%E7%81%AD%E5%89%82%E4%BB%8D%E8%B6%B3%2C%20%E6%8C%81%E7%BB%AD%E6%94%B6%E9%85%B8%22%5D%0A%20%20BRIGHT%20--%3E%20BAND%5B%22%E4%BA%A7%E9%85%B8%E4%B8%8E%E6%B7%AC%E7%81%AD%E7%9A%84%E4%BA%89%E5%A4%BA%E5%B8%A6%20%3D%20%E9%98%88%E5%80%BC%E8%BD%AE%E5%BB%93%22%5D%0A%20%20DARK%20--%3E%20BAND%0A%20%20ADDQ%5B%22%E5%8A%A0%E6%B7%AC%E7%81%AD%E5%89%82%22%5D%20--%3E%20NARROW%5B%22%E4%BA%89%E5%A4%BA%E5%B8%A6%E5%8F%98%E7%AA%84%2C%20%E9%85%B8%E7%A8%8B%E7%BC%A9%E7%9F%AD%22%5D%0A%20%20NARROW%20--%3E%20BAND%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 EUV 二次电子产酸的截面表，不写金属氧化物团簇。也不把某篇配方的 5 wt% PAG 写成所有 ArF 层的标准。Ito 早期实验剂量不是今日浸没的工艺点。</p><p>后面 PEB 课的烘箱几摄氏度，会把本课钉住的当量差再乘一个 Arrhenius 因子——化学库存与热时钟要分开调。出气与镜头污染跟 PAG 挥发性有关，那是配方卫生，不改「产酸对淬灭」的定义。</p><p><span class="marginnote">初学者容易把加淬灭剂当成纯损失（灵敏度变差）。实际上它买的是暗区安全与抗环境胺能力：不加淬灭的配方灵敏度好看，但 flare 一抬暗区剂量就起雾。灵敏度与裕量是同一笔预算的两个花法，不是两个独立旋钮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PAG 写酸的出生与产量；淬灭剂写中和与化学阈值。</li><li>有效酸是二者之差；光学 \\(I_\\mathrm{th}\\) 不能单独当规格。</li><li>加淬灭通常抬 \\(E_0\\)、抑制暗区与环境胺，并缩短后课的酸程。</li><li>加载必须联合标定，灵敏度不是无条件目标。</li><li>环境胺是额外淬灭；配方内碱提高抗污染，同时抬 \\(E_0\\)。</li><li>摩尔比比 wt% 更接近当量；193 nm 聚合物吸收不可算进 PAG 产率。</li><li>flare 抬暗区剂量时，淬灭剂是暗区保险丝。</li><li>出处：Ito &amp; Willson 化学放大；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',6))])}const C=B(d,[["render",h]]);export{f as __pageData,C as default};
